INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (1,6,'Bộ đồ ăn Timeless IFP','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773735976/9sp-time-kl-trang_bytubp.webp','Minh Long',35,'Bộ đồ ăn Timeless IFP là lựa chọn lý tưởng cho những ai yêu thích phong cách sống tối giản và tinh tế. Thiết kế theo triết lý \"Less is more\", bộ sản phẩm mang vẻ đẹp thanh thoát với màu trắng sứ tinh khiết, kết hợp cùng đường bo tròn mềm mại đặc trưng của dòng Timeless.\nSản phẩm được làm từ sứ cao cấp Minh Long, nung ở nhiệt độ trên 1380°C, không chứa chì, cadmium, an toàn cho sức khỏe, bền chắc, chống trầy xước và sử dụng được trong lò vi sóng, máy rửa chén.\nLý do nên chọn bộ này:\n- Tông trắng tinh tế – dễ kết hợp mọi kiểu không gian bàn ăn.\n- Thiết kế tối giản – hiện đại – tinh gọn.\n- 9 món tiện lợi – phù hợp cho cá nhân, cặp đôi, gia đình nhỏ.\n- Chất liệu sứ Minh Long cao cấp – không phai màu, không bám mùi, dễ vệ sinh.\nPhù hợp làm quà tặng hoặc dùng trong homestay, căn hộ studio.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (2,6,'Bộ đồ ăn Camellia','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773740413/tiepda_1_e2v3pt.webp','Minh Long',3,'Bộ đồ ăn Camellia mang phong cách sang trọng với họa tiết hoa trà tinh tế. Sản phẩm sử dụng chất liệu sứ cao cấp, bền đẹp, phù hợp cho bàn ăn gia đình hoặc tiếp khách.\nVì sao nên chọn bộ đồ ăn này?\n- Thiết kế đơn sắc hiện đại, dễ kết hợp với mọi kiểu bàn ăn\n- Sứ cao cấp Minh Long – siêu bền, dễ vệ sinh, an toàn cho sức khỏe\n- Dùng được cho máy rửa chén, lò vi sóng – tiện lợi tối đa\n- Thích hợp làm quà tặng tân gia, cưới hỏi, doanh nghiệp, khách sạn',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (3,6,'Bộ đồ ăn Jasmine','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773741517/bo-9sp-jas-trang-nga_yla16y.png','Minh Long',4,'Bộ đồ ăn Jasmine mang phong cách nhẹ nhàng, tinh tế với họa tiết hoa nhài thanh thoát.\nSản phẩm được làm từ sứ cao cấp, phù hợp cho bữa ăn gia đình và không gian trang nhã.\nVì sao nên chọn bộ đồ ăn này?\n- Thiết kế đơn sắc hiện đại, dễ kết hợp với mọi kiểu bàn ăn\n- Sứ cao cấp Minh Long – siêu bền, dễ vệ sinh, an toàn cho sức khỏe\n- Dùng được cho máy rửa chén, lò vi sóng – tiện lợi tối đa\n- Thích hợp làm quà tặng tân gia, cưới hỏi, doanh nghiệp, khách sạn',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (4,6,'Bộ đồ ăn Daisy','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773742534/24312-sm-01_d807073456cb42ac9f0796710eb65c17_master_ou5wax.png','Minh Long',7,'Bộ đồ ăn Daisy sở hữu thiết kế thanh lịch với tông màu trắng tinh khôi, mang đến nét đẹp trang nhã và sang trọng cho bàn ăn.\nSản phẩm được chế tác từ chất liệu sứ cao cấp, đảm bảo an toàn cho sức khỏe, giúp bạn yên tâm sử dụng hàng ngày.\nĐặc Điểm Nổi Bật:\n- Chất liệu sứ cao cấp, không chứa chì, cadmium, an toàn cho sức khỏe.\n- Tông màu trắng tinh khôi, dễ dàng kết hợp với nhiều phong cách bày trí bàn ăn.\n- Bộ gồm 09 sản phẩm tiện dụng, đáp ứng nhu cầu sử dụng hàng ngày.\n- Khả năng chịu nhiệt tốt, an toàn khi sử dụng trong lò vi sóng và máy rửa chén.\n- Bề mặt sứ tráng men láng mịn, hạn chế bám bẩn, dễ dàng vệ sinh.\nBộ đồ ănDaisy Trắng không chỉ giúp bữa cơm gia đình thêm trọn vẹn mà còn là sự lựa chọn lý tưởng để làm quà tặng sang trọng cho người thân, bạn bè.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (5,6,'Bộ đồ ăn Hoàng Cung','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773744001/bo-do-an-30-san-pham-hoang-cung-lac-hong-30208-00_z2uoxf.png','Minh Long I',5,'Bộ đồ ăn của sản phẩm Hoàng Cung là tuyệt tác gốm sứ cao cấp đến từ thương hiệu Minh Long I, mang đậm hơi thở truyền thống và tinh thần dân tộc. Lấy cảm hứng từ hoa văn cung đình và văn hóa Việt, bộ sản phẩm không chỉ là đồ dùng bàn ăn mà còn là biểu tượng của sự sang trọng, tinh tế và đẳng cấp.\n🌟 Đặc điểm nổi bật:\n✅ Chất liệu sứ ngọc cao cấp: Nung ở nhiệt độ trên 1.300°C, bền chắc, sáng bóng, không chứa chì – an toàn tuyệt đối cho sức khỏe người dùng.\n✅ Họa tiết độc đáo: Hoa văn vẽ vàng thủ công tinh xảo, kết hợp với sắc men trang nhã thể hiện tinh thần dân tộc, phù hợp trưng bày, tiếp khách hay làm quà tặng cao cấp.\n✅ Thiết kế sang trọng – Đậm chất hoàng cung: Từng đường nét đều được chăm chút, thể hiện đẳng cấp của người sử dụng.\n✅ Bộ sản phẩm 13 món đầy đủ: Gồm bát, đĩa, chén, tô… phục vụ bữa ăn hoàn chỉnh, thích hợp cho gia đình, nhà hàng cao cấp, khách sạn và quà tặng sự kiện.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (6,7,'Bát cơm Timeless','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773752428/chen-com-kl-timeless-trang-gom-su-minh-long-a001-591166000-0_xfa37j.webp','Minh Long',1,'Bát cơm thuộc bộ Timeless, thiết kế tối giản, màu trắng tinh tế.',1,NULL);
