INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (9,7,'Đĩa tròn Daisy','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773754137/dia-tron-ao-28-cm-daisy-bong-bay-042821312-sm-01-93a4d2e97c9b45e2b4058ec0156c2084-grande-708256cf-fd68-4282-909f-a33bc05897ac_kgbcem.png','Minh Long I',3,'Đĩa tròn Daisy thiết kế hiện đại, phù hợp trang trí bàn ăn, thuộc bộ đồ ăn Daisy',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (10,7,'Chén chấm Hoàng Cung','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773754536/chen-cham-9-cm-camellia-lac-hong_040976208-1-sm_5725bdb043d243c79330e79518c1339c_gujrc3.png','Minh Long',2,'Chén chấm cao cấp thuộc dòng Hoàng Cung, họa tiết truyền thống.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (11,8,'Nồi sứ Vesta','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773755380/Noi-duong-sinh-Vesta-3.0L-nap-Healthycook-Hong-Anh-Kim1_mmyagw.png','Healthy Cook',0,'Sứ dưỡng sinh Healthycook là dòng sản phẩm đột phá độc đáo, kết tinh của nhiều năm tâm huyết, nghiên cứu và thử nghiệm của nhà sáng lập Minh Long.\nVới chất liệu tinh tuyển từ đất hiếm thiên nhiên, lành tính, không chứa các chất độc hại, Healthycook sở hữu nhiều tính năng nổi bật góp phần đem lại những bữa ăn ngon – lành cho gia đình.\nĐẶC TÍNH SẢN PHẨM:\n- Nấu thực phẩm không cần nước mà vẫn giữ màu sắc rau củ tươi như ban đầu (dưỡng chất còn lại 70 -80%).\n- Chiên ở nhiệt độ thấp mà vẫn chín sâu, giòn lâu.\n- Nấu chín thức ăn bằng cơ chế phát ra tia hồng ngoại nên hầm nhanh mềm, tạo rất ít váng bọt nên nước trong và thơm hơn, giúp tiết kiệm thời gian và nhiên liệu.\n- Sản phẩm được nung ở nhiệt độ cao 1280 độ C giúp sản phẩm không bị rạn men, bung men trong quá trình sử dụng lâu dài\n- Bảo hành 1 năm',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (12,9,'Đũa sứ Jasmine Lys','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773756333/5cb2-8d05e38ba55f4517890c19b5ab13007b-e8822221fd3b49dc94eadac67f6703db-fe52fdbad9964f8ca6124a1a91516529-grande-47424398-546d-47c7-82b0-993882f55bf5_ygygqx.png','Minh Long LYS',1,'Được làm từ nguyên liệu sứ tinh tuyển, lành tính, an toàn cho sức khỏe.\nMặt đũa phủ men nano sáng bóng, không thấm hút gia vị, thức ăn.\nKhó bám bẩn, không bị ẩm mốc, dễ tẩy rửa, nhanh khô.\nNung ở nhiệt độ cao 1380oC đảm bảo độ cứng chắc.\nSứ cao cấp, chất lượng theo tiêu chuẩn châu Âu.\nPhù hợp để làm quà tặng; sử dụng trong gia đình, nhà hàng, khách sạn…\nHướng dẫn sử dụng và bảo quản:\n- Tránh làm rớt, va đập hoặc dùng lực tác động quá mạnh lên sản phẩm.\n- Vệ sinh sản phẩm bằng dung dịch hay các miếng tẩy rửa thông thường.\n- Bảo quản nơi khô thoáng, sạch sẽ, tránh những nơi có khả năng làm rơi vỡ sản phẩm.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (13,9,'Đũa sứ dưỡng sinh IFP','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773756576/dua-do-4f5dada2641444ceb3cae14a24657c68-grande_ezs6ab.webp','Minh Long IFP',2,'Trong dáng vẻ mảnh mai mà bền bỉ của đôi đũa là hình ảnh đồng thuận, tương trợ nhau như cốt cách người Việt, nay có thêm diện mạo mới bằng sứ do Minh Long chế tác.\n\"Một đôi hoà thuận\nXa gần xuôi ngược chờ nhau\nChút tình nâng niu nồng ấm\nSẻ chia từ buổi sơ đầu\nĐất giữ ngọc qua đá vàng gửi lại\nMột-đôi-tình\nChung thuỷ đến ngày sau...\"\nTrong cái dáng vẻ mảnh mai mà bền bỉ của đôi đũa là hình ảnh của sự đồng thuận, tìm nhau, chờ nhau, xa gần, mặn ngọt cùng nhau. Cũng thấy trong cái dáng vẻ mong manh ấy, trời, đất và người giao hoà.\nMột chiếc linh hoạt, khéo léo, tựa trên một chiếc vững vàng giữa những ngón tay người nâng đỡ- một vũ khúc của sắc hương bát ngát chan hoà. Một đôi đũa, cũng mang vẻ đẹp của sự thuỷ chung. Hai chiếc song đôi, không rời nhau giữa dòng đời xuôi ngược. \"Một đôi\", với tất cả ý nghĩa đẹp đẽ của nó, nằm ngay trong bóng dáng của sự thuỷ chung ấy. Và khi chờ nhau để cùng nâng đũa trên tay, mời nhau miếng ngon, miếng lành đầu tiên là miếng của lòng tri ân, kính trên nhường dưới, là miếng ân cần chia sẻ yêu thương. Một đôi đũa đã mang trong nó hình ảnh một gia đình đầm ấm.\nĐất thuỷ chung với người, nghìn năm giữ ngọc, qua men lửa đá vàng, một đôi thắm thiết, xin trao.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (14,9,'Gác đũa muỗng Jasmine Lys','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773756925/image-removebg-preview-1_rw2xqi.png','Minh Long LYS',0,'Gác đũa - Jasmine Lys có màu men sứ trắng ngà, đa dạng chủng loại từ chén, dĩa, tô, tách...có kiểu dáng thiết kế đồng nhất, đáp ứng đầy đủ nhu cầu sử dụng cho các loại bàn tiệc đa dạng và phong phú của khách hàng.\nGác đũa muỗng Lys giúp giữ vệ sinh bàn ăn, thiết kế nhỏ gọn, tinh tế, phù hợp với nhiều phong cách bày trí.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (15,9,'Gác đũa Misc Assortment','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773787161/gac_dua_ca_hjmqyf.png','Misc Assortment',1,'Tuyển chọn từ những nguyên liệu quý hiếm mỗi sản phẩm của Misc Assortment đảm bảo những tiêu chí cao nhất về chất lượng. Sở hữu nhiều tính năng vượt trội siêu cứng chắc, mặt men sáng bóng, khó trầy xước. Misc Assortment được nhiều người ưa chuộng và lựa chọn bởi sự cao cấp, an toàn, bền đẹp và thân thiện với môi trường.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (16,9,'Muỗng Jasmine','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773787787/f4cd4c8d12fecea097ef_b59ee5c8c3db4aab8a1943e47eda8b67_66a0b61d72344c14b7f2ad880614f1ad_hnjjlx.png','Minh Long',4,'Đặc tính sản phẩm:\n-Thân sứ siêu cứng với công nghệ phối liệu đặc biệt: Sử dụng bền lâu, hạn chế bể mẻ trong quá trình tẩy rửa.\n-Mặt men cứng, chắc: Khó trầy xước khi sử dụng dao, muỗng, nĩa thường xuyên, giữ sản phẩm luôn mới sau thời gian dài sử dụng.\n-Ứng dụng công nghệ Nano cho bề mặt men láng bóng: Giúp cho sản phẩm khó bám bẩn kể cả dầu mỡ, tiết kiệm thời gian.\n-Kiểu dáng đa dạng sang trọng phù hợp với nhiều không gian ăn uống khác nhau.\n-Độ sốc nhiệt cao (có thể sử dụng từ nóng sang lạnh và ngược lại với độ sốc nhiệt từ 0 đến 200 độ C).',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (17,9,'Muỗng Hoàng Cung','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773788271/muong-hoang-cung-kim-ngoc-a001-140429488_jzjjdy.webp','Gastroline',7,'Bộ sản phẩm Gastroline Kim Ngọc toát lên vẻ đẹp hiện đại và cuốn hút trong từng đường nét, tạo nên bức tranh sống động cho không gian ẩm thực. Với gam màu hiện đại, kiểu dáng thanh thoát phù hợp nhiều phong cách ẩm thực, Gastroline Kim Ngọc là nguồn cảm hứng bất tận cho đầu bếp thỏa thức sáng tạo và biến tấu món ăn thành một tác phẩm nghệ thuật.\nĐặc biệt, Gastroline là một trong những dòng sản phẩm trứ danh của Minh Long cùng nhà thiết kế Hans Wilhelm Seitz (nhà thiết kế đẳng cấp của Đức) từng được vinh danh là thiết kế có “ý tưởng thiết kế sản phẩm xuất sắc” tại giải Red Dot Design Award 2019 - Cuộc thi thiết kế quy mô và uy tín nhất toàn cầu.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (18,10,'Bộ trà Jasmine','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773789799/00-e044fa84-cb8f-4cfd-acbd-89b434624698_alvzg2.webp','LYS',4,'Bộ ấm trà Jasmine thiết kế thanh lịch, họa tiết tinh tế, phù hợp tiếp khách và sử dụng hàng ngày.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (19,10,'Bộ ấm trà Hoàng Cung','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773798497/00-f5e6732e-77c1-489d-9972-0804386f0860_nsci6h.webp','Minh Long I',1,'Đặc điểm nổi bật:\n- Chất liệu sứ cao cấp: Được chế tác từ nguồn nguyên liệu tinh tuyển, nung ở nhiệt độ trên 1.380°C, sản phẩm có độ bền cao, bề mặt men sáng bóng, láng mịn, chống bám bẩn và dễ dàng vệ sinh.\n- Thiết kế nhỏ gọn, tinh tế: Dung tích 0.8L vừa vặn cho những buổi thưởng trà từ 2–4 người, kiểu dáng mềm mại, cân đối, giúp giữ nhiệt tốt và thuận tiện khi sử dụng.\n- Hoa văn \"Hoàng Liên\" sang trọng: Lấy cảm hứng từ hoa sen vàng – biểu tượng của sự cao quý, thuần khiết và phú quý. Họa tiết được vẽ tay tỉ mỉ với sắc vàng kim óng ánh, mang vẻ đẹp trang nhã, quý phái.\n- An toàn tuyệt đối: Không chứa chì, cadmium; an toàn khi sử dụng trong lò vi sóng và máy rửa chén mà không ảnh hưởng đến chất lượng sản phẩm.\nBộ sản phẩm bao gồm:\n- 1 ấm trà (dung tích 0.8 lít)\n- 6 tách trà\n- 6 dĩa lót tách\n- 1 bình lọc trà (nếu có)\nỨng dụng:\n- Thích hợp cho không gian thưởng trà tại gia, văn phòng hoặc những buổi trà đạo nhẹ nhàng, ấm cúng.\n- Là món quà tặng ý nghĩa, cao cấp trong các dịp lễ tết, tân gia, mừng thọ, tri ân đối tác và khách hàng.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (20,10,'Bộ ấm trà Camellia','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773799161/daiduong1_jb2t49.webp','Minh Long',9,'ĐẶC TÍNH SẢN PHẨM:\n• Sản phẩm được sản xuất từ nguyên liệu đất sét tinh tuyển, được chọn lọc và qua các quy trình sản xuất chuyên nghiệp, kỹ thuật cao, cùng với sự tâm huyết của các nghệ nhân, đảm bảo độ bền vững cao và sử dụng lâu dài.\n• Sản phẩm được nung ở nhiệt độ cao (từ 1260℃ đến 1380℃) giúp loại bỏ tạp chất, đảm bảo an toàn cho sức khoẻ người tiêu dùng.\n• Bề mặt sản phẩm trắng sáng và không bị ố vàng sau một thời gian sử dụng. Điều này làm cho sản phẩm sứ Minh Long trở thành lựa chọn hàng đầu cho các gia đình và doanh nghiệp khi muốn trang trí không gian sống hoặc sử dụng trong các bữa tiệc quan trọng.\n• Sản phẩm được sản xuất với độ chính xác cao, tinh tế trong từng chi tiết, đảm bảo độ hoàn hảo tuyệt đối.\n• Công nghệ Nano giúp bề mặt sứ mịn, bền đẹp, kháng khuẩn, chống bám bẩn giúp dễ dàng vệ sinh.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (21,10,'Bộ ấm trà Timeless IFP','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773799426/untitled-2-33fcb174-b370-4fff-9d41-74b4ab26cd71_gukw9m.webp','Minh Long IFP',0,'Bộ trà Timeless IFP là sự kết hợp độc đáo giữa nghệ thuật gốm sứ truyền thống và biểu tượng phong thủy thiêng liêng trong văn hóa Việt Nam. Với họa tiết Tứ Linh – Long, Lân, Quy, Phụng – được thể hiện tinh xảo trên nền men trắng ngà cao cấp, điểm xuyết bằng sắc xanh dương hài hòa và viền vàng 24k sang trọng, sản phẩm không chỉ là vật phẩm thưởng trà mà còn là biểu tượng cho sức mạnh, tài lộc và phúc khí.\nBộ sản phẩm thiết kế theo phong cách cổ điển pha lẫn hiện đại, với các chi tiết được chăm chút tỉ mỉ từ bình trà, tách, dĩa lót đến chén đường và rót sữa. Đây là lựa chọn lý tưởng cho các buổi trà chiều tao nhã, những buổi tiếp khách đẳng cấp hay làm quà biếu trang trọng, ý nghĩa.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (22,10,'Bộ ấm trà Đài Các','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773799897/daicac1_n6eurh.webp','Minh Long',3,'Đặc điểm nổi bật:\n- Chất liệu sứ cao cấp từ Minh Long I – sáng bóng, bền đẹp, chịu sốc nhiệt tốt.\n- Họa tiết bạch kim tinh xảo, sang trọng, không phai màu theo thời gian.\n- Thiết kế hiện đại, phù hợp với phong cách sống thanh lịch, trang nhã.\n- An toàn cho sức khỏe, không chứa chì hay kim loại nặng độc hại.\nPhong cách:\n- Hiện đại – Sang trọng – Trang nhã – Đẳng cấp\n- Bộ trà Đài Các Bạch Kim là lựa chọn lý tưởng cho các buổi tiếp khách, thưởng trà hay làm quà tặng cao cấp trong các dịp đặc biệt như lễ Tết, tân gia, cưới hỏi.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (23,11,'Khay mứt Jasmine','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773800243/imgi-64-avatar-9-f417d222913545108853c332a00c0779_fefars.png','Minh Long',3,'Khay mứt 5 ngăn tròn Misc Assortment viền chỉ vàng là sự kết hợp hoàn hảo giữa thiết kế tinh tế và chất liệu cao cấp, mang đến vẻ sang trọng cho không gian tiếp khách trong mỗi dịp lễ Tết. Sản phẩm được chế tác từ gốm sứ cao cấp, phủ men sáng bóng, giúp dễ dàng vệ sinh và an toàn cho sức khỏe.\nPhần nắp đậy có tay cầm hình bông hoa cách điệu, điểm xuyết viền vàng ánh kim tôn lên vẻ thanh lịch và đẳng cấp. Thiết kế 5 ngăn riêng biệt giúp bạn sắp xếp nhiều loại mứt, hạt, bánh kẹo một cách gọn gàng và thẩm mỹ.\nĐặc điểm nổi bật:\n- Chất liệu: Gốm sứ cao cấp, phủ men bóng mịn.\n- Thiết kế: Tròn 5 ngăn tiện lợi, có nắp đậy kín.\n- Họa tiết: Tay cầm hình hoa, viền chỉ vàng sang trọng.\n- Màu sắc: Trắng tinh khôi, viền vàng ánh kim nổi bật.\nPhù hợp sử dụng trong dịp Tết, lễ hội, hoặc làm quà tặng ý nghĩa.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (24,11,'Khay mứt Camellia','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773800475/ca_c2qqqk.png','Minh Long',0,'🌸 Đặc điểm nổi bật:\nThiết kế 5 ngăn tiện lợi: Giúp phân loại mứt, bánh kẹo, hạt khô một cách gọn gàng, tinh tế.\nHọa tiết hoa đào viền vàng: Từng nhánh hoa đào được vẽ tỉ mỉ trên nền sứ hồng phấn trang nhã, kết hợp viền vàng ánh kim cao cấp, tạo điểm nhấn sang trọng.\nChất liệu: Gốm sứ cao cấp, phủ men bóng mịn, bền đẹp, an toàn cho sức khỏe.\nNắp đậy kín, tay cầm hoa mạ vàng: Vừa tiện dụng vừa làm nổi bật sự quý phái của sản phẩm.\nKích thước: Đường kính 24 cm, phù hợp trưng bày bàn trà, bàn tiếp khách hoặc làm quà biếu cao cấp.\n🎁 Công dụng:\nĐựng mứt, bánh kẹo, hạt dưa, hạt điều, trái cây sấy hoặc các loại hạt khô khác.\nDùng làm vật phẩm trang trí Tết hoặc quà tặng sang trọng cho người thân, đối tác.\nGóp phần làm nổi bật không gian Tết truyền thống, mang đến vẻ đẹp ấm cúng và thịnh vượng.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (25,11,'Khay mứt Hoàng Cung','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773800736/hc1_qxx3po.png','Minh Long IFP',0,'Bộ khay mứt cao cấp với thiết kế tinh xảo, mang đậm phong cách sang trọng và hiện đại. Sản phẩm gồm 5 hũ gốm có nắp, được sắp xếp gọn gàng trên đĩa tròn đường kính 31.5 cm, thuận tiện cho việc trưng bày và sử dụng trong các dịp lễ Tết hay tiếp khách.\nChất liệu: Gốm sứ cao cấp IFP, phủ men sáng bóng, bền màu theo thời gian.\nHọa tiết: Trang trí hoa văn Thiên Kim tinh tế, phối màu đỏ - vàng kim sang trọng, điểm nhấn bằng viền chỉ vàng thủ công.\nCông dụng: Dùng để đựng mứt, bánh kẹo, hạt hoặc các món ăn vặt, thích hợp cho phòng khách, bàn trà, quà biếu cao cấp.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (26,11,'Khay mứt IFP','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773800921/imgi-37-khay-mut-tron-5-ngan-24cm-nap-misc-assortment-sen-ngoc-212471456h-1-sm-4f2cfa9f4fb544d181dc12c356124c6f_rfgpsx.webp','Minh Long',13,'💎 Đặc điểm nổi bật:\nThiết kế 5 ngăn tiện dụng: Các ngăn được sắp xếp khéo léo bên trong khay tròn, giúp phân chia mứt, bánh kẹo hoặc hạt khô gọn gàng, đẹp mắt.\nHoa văn Sen Ngọc: Họa tiết hoa sen màu xanh lam kết hợp viền vàng sang trọng, tạo nên vẻ đẹp thanh lịch và quý phái.\nChất liệu: Gốm sứ cao cấp Misc Assortment, tráng men sáng bóng, an toàn cho sức khỏe, không phai màu theo thời gian.\nNắp đậy tinh xảo: Tay cầm hình hoa sen mạ vàng, điểm nhấn độc đáo cho tổng thể thiết kế.\nKích thước: Đường kính 24 cm, phù hợp trưng bày trên bàn trà, bàn khách hoặc làm quà tặng cao cấp.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (27,11,'Khay mứt Đài Các','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773801102/dc1_sm774c.png','Minh Long',2,'🌸 Đặc điểm nổi bật:\nThiết kế Ngũ Sắc tượng trưng cho ngũ hành – Kim, Mộc, Thủy, Hỏa, Thổ, mang ý nghĩa may mắn và thịnh vượng cho gia chủ.\nHọa tiết hoa nổi bật: Mỗi hũ được trang trí một loài hoa khác nhau như hoa hồng, hướng dương, lan, mai, cúc, tượng trưng cho sự tươi mới, tài lộc và hạnh phúc.\nChất liệu: Gốm sứ cao cấp IFP, phủ men sáng bóng, an toàn cho sức khỏe, bền màu theo thời gian.\nKích thước: Khay tròn đường kính 31.5 cm.\n🎁 Công dụng:\nDùng để đựng mứt, bánh kẹo, hạt khô, trái cây sấy hoặc các món ăn vặt.\nPhù hợp trưng bày trong phòng khách, bàn trà, bàn tiệc hay làm quà tặng sang trọng cho người thân, đối tác, khách hàng vào các dịp lễ Tết.\n💫 Ưu điểm:\nHoa văn in men cao cấp, không phai, không bong tróc.\nDễ vệ sinh, chịu được nhiệt độ cao.\nVẻ đẹp nghệ thuật tinh xảo, thích hợp với nhiều không gian nội thất khác nhau.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (28,12,'Bát hương Phúc Lộc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773801851/RD060723-2-removebg-preview_vnbzkb.png','Thiên Long',1,'Nguyên liệu chính để tạo nên bát hương hay một vật phẩm linh thiêng khác cho ban thờ được nhiều người tin dùng đó chính là gốm chất lượng cao.\nChỉ với những cục đất sét, những người thợ gốm lành nghề có thể tạo nên những bát hương vừa sang trọng vừa uy nghiêm.\nVì được sản xuất bởi những những bàn tay điêu luyện của các nghệ nhân nên sản phẩm sở hữu độ bền rất cao, không dễ bị phai màu hay sứt mẻ.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (29,12,'Bát hương An Khang','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773802048/bat-huong-vuot-tay-ve-sen-bat-trang-14-removebg-preview_m665rp.png','Thiên Long',1,'Bát hương An Khang mang ý nghĩa bình an, sức khỏe và thuận hòa.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (30,12,'Bát hương Tài Lộc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773804534/16_oclfhw.png','Thiên Long',3,'Bát hương màu vàng vẽ ánh kim 030723 có thiết kế khá nổi bật và gây ấn tượng với nhiều người nhờ màu men vàng sang trọng và vẽ tay ánh kim siêu tinh tế.\nNhững họa tiết hoa văn như rồng bay được vẽ ánh kim vừa mềm mại vừa tăng thêm vẻ sang trọng, cao cấp cho bát hương.\nĐể có thể tạo nên một sản phẩm đẹp hoàn hảo tới vô thực như vậy đòi hỏi tay nghề của người nghệ nhân phải chắc chắn, điêu luyện qua nhiều năm rèn luyện.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (31,12,'Bát hương Thiên Phúc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773804774/hi_w1zoxk.png','Thiên Long',2,'Bát hương Thiên Phúc mang ý nghĩa phúc lành từ trời, phù hợp không gian thờ cúng trang nghiêm.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (32,12,'Bát hương Hưng Thịnh','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773805039/1h_wtadu2.png','Minh Long',2,'Bát hương Hưng Thịnh tượng trưng cho sự phát triển bền vững và thịnh vượng lâu dài.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (33,13,'Mâm bồng Men Xanh Tím Đắp Nổi Vẽ Vàng Sen Cá ','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773805677/1_pnrsfd.png','Bát Tràng',4,'Mâm bồng sứ Bát Tràng men xanh tím đắp nổi vẽ vàng sen cá là một sản phẩm đồ thờ gốm sứ truyền thống của làng nghề Bát Tràng.\nMâm bồng sứ Bát Tràng là một vật phẩm không thể thiếu trong bộ đồ thờ cúng của người Việt.\nMâm bồng có tác dụng đựng hoa quả, trầu cau, bánh kẹo,… để dâng lên bàn thờ gia tiên, thần linh,… thể hiện lòng thành kính, hiếu thảo của con cháu đối với ông bà, tổ tiên.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (34,13,'Mâm bồng Lục bảo','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773817113/th_d3fk3p.png','Bát Tràng',0,'Mâm bồng sứ men xanh ngọc lục bảo rồng phượng là một sản phẩm cao cấp, thể hiện sự sang trọng và đẳng cấp của gia chủ.\nBằng việc lựa chọn loại nguyên liệu chế tác cao cấp, kỹ thuật làm gốm gia truyền và tài năng thiết kế, vẽ hoạ tiết của các nghệ nhân Bát Tràng, đây sẽ là vật phẩm lý tưởng mà gia chủ không nên bỏ qua.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (35,13,'Mâm bồng Tài Lộc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773817512/th-removebg-preview_xewyew.png','Bát Tràng',3,'Mâm bồng trên bàn thờ không chỉ là nơi bày lễ vật mà còn là biểu tượng của lòng hiếu thảo và biết ơn, nhắc nhở con cháu luôn gìn giữ truyền thống “Uống nước nhớ nguồn”. Việc dâng hoa quả, bánh trái lên mâm bồng thể hiện mong ước bình an, phúc lộc và sự phù hộ của tổ tiên cho gia đình.\nĐồng thời, mâm bồng còn mang ý nghĩa đầy đủ và viên mãn, thu hút tài lộc và may mắn đến với gia chủ.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (36,14,'Lục bình Phúc Lộc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773818260/thum-removebg-preview_f0xndm.png','Bát Tràng',2,'Nổi bật ở phần thân lọ là 4 bức tranh miêu tả về 4 mùa Xuân Hạ Thu Đông với những hình ảnh về loài hoa, loài cây, loài vật tương ứng của mỗi mùa.\nMùa xuân là mùa của những sự khởi đầu, hi vọng tốt đẹp về tương lai, tài lộc, hạnh phúc lứa đôi được thể hiện bằng hình ảnh của loài hoa mai và đôi công với bộ lông trải dài lộng lẫy.\nMùa hạ là hình ảnh của loài trúc xanh mướt quanh năm biểu tượng của phẩm chất con người: kiên cường, rắn rỏi đồng thời cũng mang ý nghĩa về sức khỏe, về sự may mắn, trường thọ.\nMùa thu với hình ảnh ấm áp rực rỡ của loài hoa cúc biểu tượng của sự cao sang quyền quý với ý nghĩa về sự cát tường, tài lộc và thịnh vượng.\nMùa đông là mùa của sự khắc nghiệt, nổi bật lên hình ảnh của loài Tùng mạnh mẽ, khỏe khoắn biểu tượng của khí tiết và sự trường thọ.   ',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (37,14,'Lục bình Tùng Hạc Ngũ Phúc ','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773818673/thum1-removebg-preview_gqxsgp.png','Bát Tràng',2,' Đáng được chú ý nhất chính là họa tiết Tùng Hạc Ngũ Phúc được vẽ rất tỉ mỉ, khéo léo từ đôi tay những nghệ nhân Bát Tràng.\nChi tiết Tùng Hạc Ngũ Phúc  được vẽ lên trên thân lọ là  hình ảnh rất tinh tế.\nÝ nghĩa ngũ phúc là tượng trưng cho 5 điều tốt lành may mắn trong cuộc sống Lộc bình bát tràng ngũ phúc có là tượng trưng cho sự mới mẻ, mang lại may mắn, phát tài phát lộc cho gia chủ, đồng thời cũng có ý nghĩa là sự bảo quản tài sản cho gia chủ.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (38,14,'Lục bình Bát Tràng men lam Đức Phúc','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773819006/thumm-removebg-preview_tz1uck.png','Bát Tràng',4,'Lọ lộc bình Bát Tràng này nổi bật lên hình ảnh hai chữ Đức Phúc được vẽ tay cách điệu theo lối viết thư pháp lồng vào cuốn thư tạo cảm giác trang trọng và truyền thống.\nTrên cổ lọ lộc bình là 2 câu đối:\n‘’ Đức thừa tiên tổ thiên niên thịnh\n  Phúc ấm nhi tôn bách thế vinh’’\nCâu đối là lời răn dạy của tổ tiên về giá trị của đạo đức, răn dạy con cháu lễ nghĩa làm người, biết ơn thành kính với tổ tiên cha mẹ.\nPhúc Đức đời trước đi liền với hiếu hạnh đời sau sẽ hưởng vinh hoa phú quý to lớn muôn đời cho cả dòng họ. ',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (39,14,'Lục bình Tùng Hạc Diên Niên','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773819294/tmh-removebg-preview_lsobgf.png','Bát Tràng',2,'Lục bình Tùng Hạc Diên Niên tượng trưng cho trường thọ, sức khỏe và sự bền vững.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (40,14,'Lục bình Vinh Quy Bái Tổ ','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773819660/tmhhh-removebg-preview_xue0e4.png','Bát Tràng',4,'Lọ Lộc bình Bát Tràng men lam Vinh Quy Bái Tổ có ý nghĩa sâu sắc như đạo lý ‘’Uống nước nhớ nguồn’’ nhắc nhở những người con đi học, đi làm xa quê hương khi khi thành danh phải luôn nhớ và thể hiện lòng thành kính, biết ơn quê hương đất tổ, nơi mình đã sinh ra và lớn lên.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (41,15,'Tượng Cặp Kỳ Lân','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773820271/kilan_thumb_uq3cmb.png','Minh Long I',12,'Kỳ lân là một trong tứ linh (long, lân, quy, phụng), vốn được xem là linh vật xua đuổi tà ma, hóa giải tam sát và mang đến điềm lành, được người phương Đông đặc biệt trân quý.\nTượng kỳ lân tám màu của Minh Long I là tác phẩm mỹ nghệ hiện thực hóa sinh động nét văn hóa dân gian vốn có nhưng không kém phần vương giả, hiện đại.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (42,15,'Tượng Chuột Phong Thủy','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773820414/tmhun_ympmgn.png','Minh Long II',12,'Tượng Chuột tượng trưng cho sự thông minh, nhanh nhẹn và khả năng tích lũy tài lộc.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (43,15,'Tượng Rắn Thanh Xà','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773820584/ran1_vgqqxu.png','Minh Long I',7,'Tượng Rắn biểu tượng cho trí tuệ, sự khéo léo và khả năng thích nghi trong cuộc sống.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (44,15,'Tượng Bảo Mã Phong Thủy','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773820771/th11_iuziq8.png','Minh Long II',10,'Từ thuở xa xưa, Ngựa là biểu tượng của ý chí, sức mạnh, trí tuệ và lòng trung thành.\nKhông chỉ đồng hành cùng các bậc quân vương, tráng sĩ xông pha trận mạc, Ngựa còn gắn bó với con người trên hành trình khai phá và mở mang bờ cõi.\nỞ loài vật này, hội tụ sức mạnh của thể lực, sự bền bỉ của ý chí cũng như vẻ đẹp khôi ngô tuấn tú.\nBởi thế, trong sử thi nhân loại, duy chỉ Ngựa mới được gọi là “tuấn mã”. ',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (45,15,'Tượng Rồng Long Phù Đại Khánh','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773821091/tai-xuong-90-edd3af80-c18a-4cdf-a915-cd018685d692_fatup3.png','Minh Long I',15,'Long Phù Đại Khánh kết hợp dáng đứng uy phong của Rồng thần cùng dáng hình thiêng liêng của đất nước.\nVới tư thế hiên ngang, lớp vảy long lanh rực rỡ, Rồng thần mang theo sứ mệnh cao cả và nhân văn: bảo vệ giang sơn, giữ vững cơ đồ, mang lại phúc lành cùng sự thịnh vượng.\nChế tác còn nổi bật với chi tiết mỏ vàng tượng trưng cho báu vật thiên nhiên đã ban tặng cho đất nước, cũng là kết tinh lao động sáng tạo của con người Việt Nam.\nDưới đôi tay tài hoa của các nghệ nhân Minh Long giàu kinh nghiệm, tượng Rồng Long Phù Đại Khánh còn tái hiện vẻ đẹp thiên nhiên hùng vĩ, nên thơ.\nGiữa nắng vàng rực rỡ và biển cả bao la, Rồng mang nguồn năng lượng dồi dào của đất trời, trao truyền sức mạnh để tiếp tục gìn giữ, phát huy những giá trị tinh hoa của văn hóa, con người và đất nước.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (46,16,'Tượng cô gái gốm','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773821674/thutm-removebg-preview_puu3ht.png','Fixory',34,'Tượng cô gái gốm mang vẻ đẹp nhẹ nhàng, thanh lịch, phù hợp trang trí phòng khách, kệ sách hoặc bàn làm việc.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (47,16,'Tượng chim gốm nghệ thuật','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773821875/mtmtm-removebg-preview_iyllo2.png','Bát Tràng',27,'Tượng chim gốm mang ý nghĩa tự do và nhẹ nhàng, phù hợp decor không gian sống hiện đại.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (48,16,'Tượng voi gốm decor','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773822165/voi_tht-removebg-preview_iowdft.png','Bát Tràng',46,'Tượng voi gốm mang phong cách trang trí hiện đại, biểu tượng cho sự bền bỉ và may mắn.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (49,16,'Tượng Gà Đại Các','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773822733/ga_kiv27f.png','Bát Tràng',22,'Tượng gà gốm mang phong cách tối giản, tạo điểm nhấn tinh tế cho không gian sống.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (50,17,'Bình hoa Đại Các','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773823016/mtmt_ayvor6.webp','Bát Tràng',68,'Ưu điểm nổi bật\n✔️ Chất lượng gốm sứ cao cấp: Được nung ở nhiệt độ cao, đảm bảo độ bền, không dễ nứt vỡ, an toàn với môi trường.\n✔️ Hoa văn vẽ tay tinh xảo: Mỗi sản phẩm là một tác phẩm nghệ thuật độc nhất, không trùng lặp.\n✔️ Kích thước 41 cm cân đối: Phù hợp cho nhiều không gian trang trí khác nhau từ phòng khách, phòng làm việc đến sảnh lễ tân.\n✔️ Phù hợp làm quà tặng cao cấp: Gửi gắm giá trị thẩm mỹ và sang trọng cho người nhận.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (51,17,'Bình hoa trang trí - Hoa Đào','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773823151/haha_cdbbmz.webp','Bát Tràng',180,'• Sản phẩm được sản xuất từ nguyên liệu đất sét tinh tuyển, được chọn lọc và qua các quy trình sản xuất chuyên nghiệp, kỹ thuật cao, cùng với sự tâm huyết của các nghệ nhân, đảm bảo độ bền vững cao và sử dụng lâu dài.\n• Sản phẩm được nung ở nhiệt độ cao (từ 1260℃ đến 1380℃) giúp loại bỏ tạp chất, đảm bảo an toàn cho sức khoẻ người tiêu dùng.\n• Bề mặt sản phẩm trắng sáng và không bị ố vàng sau một thời gian sử dụng. Điều này làm cho sản phẩm sứ Minh Long trở thành lựa chọn hàng đầu cho các gia đình và doanh nghiệp khi muốn trang trí không gian sống hoặc sử dụng trong các bữa tiệc quan trọng.\n• Sản phẩm được sản xuất với độ chính xác cao, tinh tế trong từng chi tiết, đảm bảo độ hoàn hảo tuyệt đối.\n• Công nghệ Nano giúp bề mặt sứ mịn, bền đẹp, kháng khuẩn, chống bám bẩn giúp dễ dàng vệ sinh.',1,NULL);
INSERT INTO `SanPham` (`MaSanPham`, `MaDanhMuc`, `TenSanPham`, `Thumbnail`, `ThuongHieu`, `LuotXem`, `MoTa`, `TrangThai`, `deleted_at`) VALUES (52,17,'Bình hoa - Hoa sen nền Vàng','https://res.cloudinary.com/dcmwz0uis/image/upload/v1773823508/sen_xqxoi8.webp','Bát Tràng',199,'Bình hoa họa tiết hoa sen mang đậm nét truyền thống Việt.\nLƯU Ý SỬ DỤNG BẢO QUẢN:\n• Sản phẩm có thể được sử dụng trong nhiều mục đích khác nhau, từ trang trí nhà cửa, phòng khách, phòng ngủ, phòng ăn cho đến các không gian công cộng, khách sạn, nhà hàng, quán cà phê.\n• Sản phẩm được thiết kế đa dạng về kiểu dáng và mẫu mã, phù hợp với nhiều phong cách trang trí khác nhau.\n• Sản phẩm không sử dụng trong lò vi sóng, lò nướng, máy rửa chén.\n• Không dùng sản phẩm để đựng các loại thực phẩm có tính ăn mòn cao như chanh, giấm, muối mặn…, giữ những thực phẩm này không tiếp xúc trực tiếp với những vùng sản phẩm được trang trí bằng kim loại quý (vàng, bạch kim)\n• Không nung trực tiếp sản phẩm trên lửa.\n• Làm sạch sản phẩm bằng vải mềm, miếng tẩy rửa và dung dịch tẩy rửa thông thường',1,NULL);
